import{_ as e,o as i,c as a,a2 as o}from"./chunks/framework.BaXgE4DV.js";const p=JSON.parse('{"title":"감사 글과 공유","description":"","frontmatter":{},"headers":[],"relativePath":"features/gratitudes.md","filePath":"features/gratitudes.md","lastUpdated":1792333265000}'),d={name:"features/gratitudes.md"};function r(s,t,l,c,n,h){return i(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="감사-글과-공유" tabindex="-1">감사 글과 공유 <a class="header-anchor" href="#감사-글과-공유" aria-label="Permalink to &quot;감사 글과 공유&quot;">​</a></h1><h2 id="작성" tabindex="-1">작성 <a class="header-anchor" href="#작성" aria-label="Permalink to &quot;작성&quot;">​</a></h2><p><code>/write</code>는 <strong>직접 작성</strong> 화면으로 바로 열립니다. 입력란 위에 &quot;제목&quot;·&quot;내용&quot;·&quot;누가 볼 수 있나요?&quot; 라벨은 두지 않고(안내 문구와 스크린 리더용 이름만), 상단 로고는 홈과 같은 크기입니다. 저장 버튼 바로 아래에 잔잔한 배너(새싹 로고 + &quot;질문으로 쓰기&quot;, 따뜻한 그러데이션, 오른쪽 아래 흐린 새싹, 흰 알약 버튼)가 있어 첫 화면 안에 보이고, 질문 하나(오늘의 질문 — 홈 화면 위젯과 같은 질문, &quot;다른 질문&quot;으로 바꾸기)와 <strong>[이 질문으로 감사 적기]</strong> 가 보입니다. 쓰려다가 막히면 그 질문으로 &quot;질문으로 쓰기&quot;를 시작합니다. 어느 쪽이든 마지막에 공개 범위를 고르고 저장합니다.</p><table tabindex="0"><thead><tr><th>모드</th><th>흐름</th></tr></thead><tbody><tr><td>직접 작성 (처음 화면)</td><td>제목과 내용을 직접 입력 → 공개 범위 → 저장</td></tr><tr><td>질문으로 쓰기</td><td>[이 질문으로 감사 적기] → 그 질문에 답변 → 이어지는 질문 → 답변(건너뛰기 가능) → 답변으로 만든 초안 → 제목 입력·수정 → 공개 범위 → 저장. 뒤로 가면 직접 작성 화면</td></tr></tbody></table><p>질문으로 쓰기는 주소가 따로 있어(<code>/write?mode=guided&amp;qtext=…&amp;qid=…</code>, 위젯 링크와 같음) 휴대폰 뒤로 가기(Android 뒤로, iOS 스와이프)나 화면의 ←로 쓰기 화면에 돌아옵니다. 질문으로 저장하면 그 주소는 홈으로 바뀌어, 홈에서 뒤로 가면 쓰기 화면입니다. 직접 작성 중인 제목·내용은 이 기기(세션 저장소)에 남아 있어, 질문으로 쓰기에 갔다가 돌아오거나 화면을 떠났다 와도 이어서 씁니다. 저장하면 지웁니다.</p><p>두 모드 모두 화면에서 제목과 내용을 요구합니다(모두의 감사방 <a href="/grato-docs/features/circles#daily-topic">오늘의 주제</a>에 답할 때만 제목을 쓰지 않아도 됨, <code>/write?topic=…</code>). 질문으로 쓰기는 운영자가 선정한 질문으로 동작하고, 답변과 초안은 기기 안에서 만듭니다. → <a href="/grato-docs/features/guided-writing">질문으로 쓰기</a></p><h3 id="visibility" tabindex="-1">공개 범위: 기본은 나만 보기 <a class="header-anchor" href="#visibility" aria-label="Permalink to &quot;공개 범위: 기본은 나만 보기 {#visibility}&quot;">​</a></h3><p>감사 글은 기본이 <strong>개인 기록</strong>입니다. Circle에 나누는 것은 글을 쓸 때마다 직접 고르는 선택입니다. → <a href="/grato-docs/decisions#adr-12">결정 기록 #12</a></p><table tabindex="0"><thead><tr><th>선택 (나만 보기 / Circle에 공유)</th><th>저장</th><th>볼 수 있는 사람</th><th>안내 문구</th><th>저장 버튼</th></tr></thead><tbody><tr><td>나만 보기 (기본, 항상 처음 선택됨)</td><td><code>groupId: null</code></td><td>작성자</td><td>나만 볼 수 있어요</td><td>저장하기</td></tr><tr><td>Circle에 공유 + Circle 선택</td><td><code>groupId: &lt;Circle ID&gt;</code></td><td>작성자, 그 Circle의 현재 멤버</td><td>선택한 Circle 멤버만 볼 수 있어요</td><td>Circle에 공유하기</td></tr></tbody></table><ul><li>두 모드가 같은 컴포넌트 <code>src/components/write/VisibilityPicker.jsx</code>를 씁니다.</li><li>Circle은 미리 선택되지 않습니다. &quot;Circle에 공유&quot;를 고르면 내 Circle 목록이 칩으로 나오고, Circle을 고르기 전까지는 &quot;공유할 Circle을 선택해주세요&quot;가 보이며 저장할 수 없습니다.</li><li>Circle이 없으면 &quot;Circle에 공유&quot;는 꺼져 있고, 안내는 &quot;나만 볼 수 있어요. Circle에 참여하면 함께 나눌 수도 있어요&quot;입니다.</li><li><code>/write</code>로 바로 들어와도 Circle 목록을 읽어 옵니다(<code>useGroups({ skipIfLoaded: true })</code>). 목록에 없는 Circle(탈퇴·삭제)로는 저장하지 않습니다.</li><li>저장 후 홈은 글이 간 곳(내 기록 또는 그 Circle 탭)을 엽니다.</li><li>&quot;Circle에 공유&quot;를 고르면 &quot;다른 사람에게 불쾌감을 주거나 사생활이 드러나는 내용은 없는지 올리기 전에 한 번 더 살펴봐 주세요. 공유한 글은 언제든 지울 수 있어요.&quot;를 함께 보여 줍니다. 다른 멤버에 대한 배려와 함께 개인정보 보호법 제23조제3항의 사전 안내(드러날 수 있는 정보와 되돌리는 방법)를 겸합니다. 건강·신념 같은 민감한 정보의 종류는 개인정보처리방침 7항에 적혀 있습니다.</li><li>&quot;나만 보기&quot;는 Circle 공유에 관한 선택입니다. 외부 공유 링크는 이와 별개로 작성자가 따로 공개를 골라야 열립니다. → <a href="#sharing">외부 공유</a></li><li>Circle은 공개 목록이나 검색이 없고 초대 코드로만 참여합니다. → <a href="/grato-docs/features/circles">Circle</a></li></ul><h3 id="bookmarks" tabindex="-1">저장 (책갈피) <a class="header-anchor" href="#bookmarks" aria-label="Permalink to &quot;저장 (책갈피) {#bookmarks}&quot;">​</a></h3><p>다시 보고 싶은 글을 저장해 따로 모아 봅니다. 내 글이든 Circle 글이든 볼 수 있는 글이면 저장할 수 있고, 저장한 목록은 나만 봅니다(운영자도 못 봄).</p><ul><li>피드 카드 오른쪽 아래와 글 상세의 <strong>[저장]</strong> → 누르면 <strong>[저장됨]</strong>(채운 책갈피), 다시 누르면 취소. 바로 반영됩니다.</li><li>마이페이지 숫자 칸 아래의 <strong>&quot;저장한 감사 N개 ›&quot;</strong> → <code>/saved</code>: 최근에 저장한 순으로 20개씩(&quot;더 보기&quot;). 카드는 피드와 같아 공감·댓글·저장 취소를 그 자리에서 하고, 작성자 이름 아래에 어디에 쓴 글인지(Circle 이름, &quot;나만 보기&quot;, &quot;링크 공개&quot;, 나간 Circle이면 &quot;지난 Circle&quot;)가 보입니다.</li><li>저장한 뒤 글이 지워졌거나 그 Circle에서 나갔으면 &quot;더 볼 수 없는 글이에요 — 지워졌거나, 나간 Circle의 글이에요&quot;와 <strong>[목록에서 빼기]</strong>. 차단한 사용자의 글은 &quot;차단한 사용자의 글이에요&quot;.</li><li>저장 목록은 <code>users/{uid}/bookmarks</code>에 있고 계정을 삭제하면 함께 지워집니다. → <a href="/grato-docs/architecture/data-model#bookmarks">데이터 모델</a></li><li>분석 이벤트 <code>gratitude_bookmarked</code> <code>{ saved }</code>.</li></ul><h3 id="my-feed" tabindex="-1">홈: 내 기록 <a class="header-anchor" href="#my-feed" aria-label="Permalink to &quot;홈: 내 기록 {#my-feed}&quot;">​</a></h3><p>홈 피드의 첫 탭은 항상 &quot;내 기록&quot;(자물쇠 아이콘)이고 기본으로 선택됩니다. Circle이 없어도 있습니다. 본인 글(개인 글과 Circle에 공유한 글)을 최신순으로 보여 주고, Circle 탭이 그 뒤에 이어집니다.</p><ul><li>첫 20개는 실시간(<code>userId == 나</code>, <code>createdAt</code> 내림차순, <code>limit(20)</code>), 그 뒤는 &quot;더 보기&quot;로 20개씩 읽습니다. Circle 탭도 같은 방식입니다(<code>src/lib/feed.js</code>). → <a href="/grato-docs/architecture/client#home-feeds">클라이언트 상태</a></li><li>카드에는 작성자 대신 시간과 공개 범위가 작게 표시됩니다: &quot;나만 보기&quot;(자물쇠), 링크로 공개한 개인 글이면 &quot;링크 공개&quot;, Circle에 공유한 글이면 Circle 이름(떠났거나 삭제된 Circle이면 &quot;Circle&quot;).</li><li>글이 없으면 &quot;아직 남긴 기록이 없어요&quot;와 &quot;Grato 쓰기&quot; 버튼을 보여 줍니다.</li><li>실시간 구독이 실패하면(네트워크, 권한, 준비 중인 인덱스) &quot;기록이 없어요&quot;가 아니라 &quot;기록을 불러오지 못했어요&quot;와 &quot;다시 시도&quot;를 보여 줍니다.</li><li>Circle이 없으면 탭 아래에 Circle 만들기·참여를 권하는 카드(&quot;함께 나누고 싶은 사람이 있나요?&quot;)를 내 기록과 함께 보여 줍니다.</li></ul><h3 id="save" tabindex="-1">저장 <a class="header-anchor" href="#save" aria-label="Permalink to &quot;저장 {#save}&quot;">​</a></h3><p><code>createGratitude(userId, groupId, {title, content})</code>가 한 번의 <code>setDoc</code>으로 글을 만듭니다.</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  userId, groupId,            </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// groupId는 Circle ID 또는 null</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  title, content,             </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 제목 0~100자, 내용 1~3000자</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  authorName, authorTag, authorPublicName, authorPhotoURL, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 공개 프로필 사본</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  reactions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;❤️&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [], </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;🙏&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [], </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;✨&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [], </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;🔥&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [] },</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  isPublic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  createdAt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">serverTimestamp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li>작성자 필드는 저장 직전에 <code>publicProfiles/{uid}</code>를 읽어 채웁니다. 규칙이 원본과 같은지 확인합니다.</li><li>문서 ID는 클라이언트 자동 ID입니다(<code>doc(collection(...))</code>).</li><li>더 이상 멤버가 아닌 Circle에 저장하려 하면 규칙이 거부하고, 화면은 &quot;이 Circle에는 더 이상 글을 남길 수 없어요&quot;를 보여 줍니다.</li><li>Circle에 처음 나눈 글이면 저장 뒤 &quot;Circle 멤버에게 알렸어요&quot;가 잠깐 보이고, 서버가 글에 <code>firstShare: true</code>를 써서 Circle 피드에 7일 동안 &quot;처음 나눈 감사&quot;가 붙습니다 → <a href="/grato-docs/features/circles#first-share">첫 나눔</a></li><li>저장 후 통계·배지·알림은 <code>onGratitudeCreated</code> 트리거가 처리합니다. 트리거가 반영되기 전 잠깐 동안은 <code>authStore.lastPostDateKey</code>로 &quot;오늘 기록함&quot;을 미리 표시합니다.</li></ul><h3 id="delete" tabindex="-1">수정과 삭제 <a class="header-anchor" href="#delete" aria-label="Permalink to &quot;수정과 삭제 {#delete}&quot;">​</a></h3><p>글 내용은 저장 후 고칠 수 없습니다. <strong>작성자는 글을 지울 수 있습니다.</strong></p><ul><li>글 카드와 글 상세의 &quot;⋯&quot; 메뉴 → &quot;이 Grato 삭제하기&quot; → 확인 창(&quot;삭제하면 되돌릴 수 없어요. 달린 댓글과 리액션도 함께 사라지고, 공유 링크로도 더 이상 볼 수 없어요.&quot;)</li><li>클라이언트는 문서 하나만 지우고(<code>deleteGratitude</code>), 불러온 피드에서 바로 뺍니다(<code>removeFromFeeds</code>). 오늘 쓴 글이면 &quot;오늘 기록함&quot; 미리 표시도 지웁니다.</li><li>나머지는 서버 트리거 <code>onGratitudeDeleted</code>가 합니다: 댓글 삭제, 통계(연속일·이번 달 수) 재계산, 그 달에 글이 남지 않으면 공유한 캘린더 월 비공개. <strong>받은 배지는 유지</strong>합니다. → <a href="/grato-docs/architecture/cloud-functions#gratitude-deleted">Cloud Functions</a>, <a href="/grato-docs/features/stats-badges#rebuild">글을 지웠을 때</a></li><li>공유 링크는 바로 &quot;비공개&quot;가 됩니다(문서가 없음).</li><li>운영자도 신고된 글을 지울 수 있고, 계정을 삭제하면 그 사람의 글이 모두 지워집니다. 같은 트리거가 정리합니다.</li></ul><h3 id="다른-사람에게-보이지-않는-글" tabindex="-1">다른 사람에게 보이지 않는 글 <a class="header-anchor" href="#다른-사람에게-보이지-않는-글" aria-label="Permalink to &quot;다른 사람에게 보이지 않는 글&quot;">​</a></h3><ul><li><strong>차단</strong>: 내가 차단한 사람의 글·댓글은 내 화면에서 빠집니다.</li><li><strong>숨김</strong>: 신고나 자동 검사로 숨긴 글·댓글은 작성자에게만 &quot;검토 중이에요&quot;로 보입니다. 숨긴 Circle 글은 Circle 피드에서 빠지고 작성자의 내 기록에만 남습니다.</li></ul><p>→ <a href="/grato-docs/features/safety">신고·차단과 자동 숨김</a></p><h2 id="리액션" tabindex="-1">리액션 <a class="header-anchor" href="#리액션" aria-label="Permalink to &quot;리액션&quot;">​</a></h2><p>이모지 4종(❤️ 🙏 ✨ 🔥)을 Slack처럼 칩으로 보여 줍니다. 각 이모지는 누른 사람의 uid 배열입니다.</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">updateDoc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ref, { [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`reactions.\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">emoji</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]: hasReacted </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> arrayRemove</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(uid) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> arrayUnion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(uid) })</span></span></code></pre></div><ul><li>글을 읽을 수 있는 사람(작성자, 현재 Circle 멤버)만 누를 수 있습니다.</li><li>규칙은 <strong>자기 uid의 추가·제거만</strong> 허용하고, 리액션과 다른 필드를 함께 바꾸는 것을 막습니다.</li><li>다른 사람이 새로 누르면 작성자에게 알림이 갑니다(본인 리액션 제외). → <a href="/grato-docs/features/notifications">알림</a></li></ul><h2 id="댓글" tabindex="-1">댓글 <a class="header-anchor" href="#댓글" aria-label="Permalink to &quot;댓글&quot;">​</a></h2><p><code>gratitudes/{id}/comments</code> 하위 컬렉션입니다.</p><p>피드 카드(홈의 내 기록·Circle 탭, 저장한 감사)의 <strong>[댓글 N]</strong> 을 누르면 화면을 옮기지 않고 카드 안에 댓글이 펼쳐집니다(다시 누르면 접힘). 그 자리에서 읽고 쓰고 지우고 신고·차단합니다. 댓글 코드는 처음 펼칠 때 불러옵니다. 긴 본문은 카드의 &quot;더보기&quot;로 펼칩니다. 글 상세(<code>/gratitude/{id}</code>)는 알림·공유 링크로 들어올 때 씁니다. 분석 이벤트 <code>comments_opened</code> <code>{ where: &#39;feed&#39; }</code>.</p><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>읽기·쓰기</td><td>부모 글을 읽을 수 있는 사람</td></tr><tr><td>길이</td><td>1~500자</td></tr><tr><td>표시</td><td>오래된 순, 최대 100개</td></tr><tr><td>수정</td><td>불가 (내용·작성자). 공감만 바꿀 수 있음 → <a href="#comment-reactions">댓글 공감</a></td></tr><tr><td>삭제</td><td>댓글 작성자 또는 글 작성자 (&quot;⋯&quot; 메뉴, 확인 창)</td></tr><tr><td>신고·차단</td><td>다른 사람의 댓글은 &quot;⋯&quot; 메뉴에서 신고·차단 → <a href="/grato-docs/features/safety">신고·차단</a></td></tr><tr><td>자동 숨김</td><td>Circle 글의 댓글에 욕설·혐오 표현이 있으면 숨김 (작성자에게는 &quot;검토 중이에요&quot;)</td></tr><tr><td>댓글 수</td><td>부모의 <code>commentCount</code>(작성자별 <code>commentAuthors</code>)를 <code>onCommentCreated</code>/<code>onCommentDeleted</code>가 유지 (클라이언트는 쓰지 않음). 숨긴 댓글도 셈. 화면에는 내가 차단한 사람의 댓글을 뺀 수</td></tr></tbody></table><h3 id="comment-reactions" tabindex="-1">댓글 공감 <a class="header-anchor" href="#comment-reactions" aria-label="Permalink to &quot;댓글 공감 {#comment-reactions}&quot;">​</a></h3><p>댓글에도 공감을 답니다(ADR-32). 댓글 본문 아래 작은 줄에 공감이 있는 이모지만 칩으로 보이고, 끝의 작은 버튼(😊+)으로 고릅니다.</p><ul><li><strong>이모지는 기본 4종(❤️ 🙏 ✨ 🔥)만.</strong> 배지로 받는 보상 공감(🌸 🍀 🌈)은 글에만 씁니다.</li><li><strong>숫자는 작게.</strong> 칩 안의 숫자는 이모지보다 작은 회색 글자입니다. 댓글은 <strong>언제나 오래된 순</strong>이고 공감 수로 정렬하거나 강조하지 않습니다.</li><li><strong>누를 수 있는 사람</strong>: 부모 글을 읽을 수 있는 사람(작성자, 현재 Circle 멤버). 자기 댓글에도 누를 수 있습니다. 숨긴 댓글(작성자에게 &quot;검토 중이에요&quot;)에는 누를 수 없고, 운영자가 신고를 보러 들어온 화면에서는 칩만 보입니다.</li><li><strong>차단</strong>: 내가 차단한 사람의 공감은 숫자에서 뺍니다(글 공감과 같음).</li><li><strong>모두의 감사방</strong>에서도 같습니다. 누가 눌렀는지는 보여 주지 않으므로 별명·프로필을 읽지 않습니다.</li><li><strong>알림은 보내지 않습니다.</strong> 글 공감 알림(<code>onReactionUpdated</code>)과 달리 댓글 공감에는 서버 트리거가 없습니다.</li><li>저장은 댓글 문서의 <code>reactions</code> 맵(<code>{ 이모지: uid[] }</code>, 첫 공감 전에는 없음)이고, 쓰는 모양은 글 공감과 같습니다. 규칙 → <a href="/grato-docs/architecture/security-rules#comment-reactions">보안 규칙</a></li><li>분석 이벤트 <code>comment_reaction_added</code> <code>{ emoji }</code> (관리자 &quot;오늘&quot; 숫자의 공감 칸에는 넣지 않음).</li><li>계정을 삭제하면 다른 사람 댓글에 남긴 내 공감도 지웁니다(<code>deleteAccount</code>).</li></ul><h2 id="sharing" tabindex="-1">외부 공유 (opt-in) <a class="header-anchor" href="#sharing" aria-label="Permalink to &quot;외부 공유 (opt-in) {#sharing}&quot;">​</a></h2><p>공유 링크는 <strong>작성자가 공개하기로 한 것만</strong> 보여 줍니다. 링크를 아는 것만으로는 내용을 볼 수 없습니다. → <a href="/grato-docs/decisions#adr-6">결정 기록 #6</a></p><table tabindex="0"><thead><tr><th>대상</th><th>공개 상태 저장 위치</th><th>공개하는 곳</th><th>공유 URL</th></tr></thead><tbody><tr><td>감사 글</td><td><code>gratitudes/{id}.isPublic</code>, <code>sharedAt</code></td><td>글 카드·상세의 공유 버튼 (작성자)</td><td><code>/share/gratitude/{id}</code></td></tr><tr><td>캘린더 월</td><td><code>publicShares/{uid}.calendarMonths</code></td><td>MyPage 캘린더의 링크 공유</td><td><code>/share/calendar/{uid}/{YYYY-MM}</code></td></tr><tr><td>배지</td><td><code>publicShares/{uid}.badgeIds</code></td><td>배지 상세 시트의 공유</td><td><code>/share/badge/{badgeId}/{uid}</code></td></tr></tbody></table><h3 id="공개-흐름" tabindex="-1">공개 흐름 <a class="header-anchor" href="#공개-흐름" aria-label="Permalink to &quot;공개 흐름&quot;">​</a></h3><ol><li>공개되지 않은 것을 공유하려 하면 확인 창이 뜹니다. 예: &quot;이 감사를 링크가 있는 누구나 볼 수 있게 공개할까요?&quot; 감사 글은 &quot;다른 사람에게 불쾌감을 주거나 사생활이 드러나는 내용은 없는지 한 번 더 살펴봐 주세요. 언제든 공개를 취소할 수 있어요.&quot;가 함께 나옵니다.</li><li>확인하면 공개 저장을 <strong>기다리지 않고</strong> 바로 공유 시트(Web Share API, 없으면 클립보드 복사)를 엽니다. Safari는 네트워크 왕복 뒤에는 사용자 동작으로 인정하지 않아 공유 시트가 막히기 때문입니다.</li><li>공개 저장이 실패하면 상태를 되돌리고 &quot;공개 설정에 실패했어요&quot;를 알립니다.</li><li>배지는 공유 시트를 닫으면(취소) 방금 한 공개를 되돌립니다.</li></ol><p>공개는 언제든 취소할 수 있습니다(글 상세의 &quot;공개 취소&quot;, 캘린더의 비공개 전환). 공유 페이지는 캐시하지 않아 바로 반영됩니다. 숨김 처리된 글은 공개로 바꿀 수 없고, 이미 공개된 글이 숨겨지면 공유 페이지가 &quot;비공개&quot;로 보입니다. 공유 페이지 아래에는 로그인 없이 쓸 수 있는 &quot;신고하기&quot;(고객지원 이메일)가 있습니다.</p><h3 id="공유-페이지가-보여-주는-것" tabindex="-1">공유 페이지가 보여 주는 것 <a class="header-anchor" href="#공유-페이지가-보여-주는-것" aria-label="Permalink to &quot;공유 페이지가 보여 주는 것&quot;">​</a></h3><p>공유 URL은 Hosting rewrite로 <code>shareRenderer</code>가 렌더링합니다(Admin SDK로 읽음). 로그인하지 않은 방문자도 볼 수 있습니다.</p><table tabindex="0"><thead><tr><th>페이지</th><th>공개된 경우</th><th>공개되지 않은 경우</th></tr></thead><tbody><tr><td>감사 글</td><td>제목, 내용, 작성자 공개 이름, 날짜(KST), JSON-LD <code>Article</code></td><td>&quot;비공개 감사&quot; 안내만, <code>noindex</code></td></tr><tr><td>캘린더 월</td><td>표시 이름, 그 달(KST)에 기록한 날, 개수, 현재 연속일</td><td>&quot;비공개 캘린더&quot; 안내만 (이름도 숨김), <code>noindex</code></td></tr><tr><td>배지</td><td>배지 정보 + 사용자 이름 + 획득/도전 중 여부</td><td>배지 정의(이름·아이콘·설명)만, 사용자 정보 없음, <code>noindex</code></td></tr><tr><td>초대 (<code>/invite/{code}</code>)</td><td>Circle 이름, 설명, 인원</td><td>코드가 없으면 &quot;유효하지 않은 초대&quot;, <code>noindex</code></td></tr></tbody></table><ul><li>페이지마다 <code>&lt;title&gt;</code>, description, Open Graph, Twitter 카드를 채워 메신저·SNS 미리보기가 나오게 합니다.</li><li>서버는 데이터를 <code>window.__SHARE_DATA__</code>로 함께 내려 주고, React 페이지(<code>ShareGratitudePage</code> 등)가 이것으로 화면을 그립니다.</li><li>본인이 자기 캘린더 공유 페이지를 열면, 아직 공개하지 않은 달도 Firestore에서 직접 읽어 <strong>미리보기</strong>로 보여 줍니다(규칙상 본인 글만 읽을 수 있음).</li></ul><h3 id="short-links" tabindex="-1">짧은 링크 <a class="header-anchor" href="#short-links" aria-label="Permalink to &quot;짧은 링크 {#short-links}&quot;">​</a></h3><p>공유 링크는 종류별 접두어가 붙은 짧은 주소로도 열립니다. 새 도메인 없이 <code>grato.today</code>를 쓰고, <strong>링크에 uid가 보이지 않습니다.</strong> → <a href="/grato-docs/decisions#adr-42">결정 기록 #42</a></p><table tabindex="0"><thead><tr><th>종류</th><th>짧은 링크</th><th>같은 페이지의 긴 링크</th></tr></thead><tbody><tr><td>감사 글</td><td><code>grato.today/g/{코드}</code></td><td><code>/share/gratitude/{id}</code></td></tr><tr><td>캘린더 월</td><td><code>grato.today/c/{코드}</code></td><td><code>/share/calendar/{uid}/{YYYY-MM}</code></td></tr><tr><td>배지</td><td><code>grato.today/b/{코드}</code></td><td><code>/share/badge/{badgeId}/{uid}</code></td></tr><tr><td>초대</td><td><code>grato.today/i/{초대 코드}</code></td><td><code>/invite/{초대 코드}</code></td></tr><tr><td>캠페인</td><td><code>grato.today/go/{이름}</code></td><td>UTM이 붙은 사이트 주소 → <a href="/grato-docs/operations/deploy#campaign-links">캠페인 링크</a></td></tr></tbody></table><ul><li>코드는 초대 코드와 같은 글자 8자리(대문자·숫자, <code>0</code> <code>O</code> <code>1</code> <code>I</code> 없음). 소문자로 옮겨 적어도 열립니다. 초대는 새 코드 없이 지금 초대 코드를 그대로 씁니다.</li><li>코드는 서버가 만듭니다(<code>createShortLink</code>). <strong>본인 것이고 지금 공개된 것만</strong> 만들 수 있고, 같은 대상이면 늘 같은 코드입니다. 새 코드는 계정당 하루 100개까지.</li><li><strong>공유하기가 보내는 링크</strong>: 앱은 공유 시트를 열기 전에 짧은 링크를 최대 1.5초 기다리고(방금 공개한 것이면 공개 저장이 끝난 뒤), 못 받으면 긴 링크를 보냅니다. 웹은 기다리지 않습니다 — Safari는 네트워크 왕복 뒤에는 공유 시트를 막기 때문입니다. 대신 이미 공개된 것을 보여 줄 때(글 상세, 공개한 캘린더 달, 공개한 배지의 시트) 그리고 공개 저장이 끝난 직후에 짧은 링크를 미리 받아 두고, 받아 둔 것이 있으면 그것을, 없으면 긴 링크를 보냅니다. 그래서 웹에서 처음 공개하며 공유하면 긴 링크, 그다음부터 짧은 링크입니다. 어느 쪽이든 짧은 링크 때문에 공유가 막히지 않습니다(<code>src/lib/share.js</code>, <code>src/lib/shortLinks.js</code>).</li><li>초대 메시지는 늘 <code>grato.today/i/{초대 코드}</code>입니다(서버 호출 없음). 메시지 문구는 그대로입니다.</li><li>짧은 링크도 볼 때마다 지금의 공개 여부를 확인합니다. 공개를 끄면 짧은 링크에서도 곧바로 &quot;비공개&quot;가 보이고, 다시 공개하면 같은 링크가 다시 열립니다. 글을 지우거나 계정을 지우면 짧은 링크도 지워져 &quot;찾을 수 없어요&quot;가 됩니다.</li><li>미리보기(카카오톡·인스타그램 등)는 짧은 링크 그대로 긴 링크와 같은 제목·설명·이미지를 냅니다(리디렉션 없음). 짧은 링크 페이지의 데이터(<code>__SHARE_DATA__</code>)에도 uid가 없습니다.</li><li>지금까지 보낸 긴 링크는 그대로 열립니다.</li><li>코드를 맞혀 열어도 이미 공개한 것만 보입니다(약 1.1×10¹²가지, 형식이 틀린 코드는 서버가 읽지도 않음).</li><li>데이터 → <a href="/grato-docs/architecture/data-model#short-links">데이터 모델</a>, 서버 → <a href="/grato-docs/architecture/cloud-functions#sharerenderer">shareRenderer</a></li></ul><h3 id="공유-문구" tabindex="-1">공유 문구 <a class="header-anchor" href="#공유-문구" aria-label="Permalink to &quot;공유 문구&quot;">​</a></h3><p><code>src/lib/share.js</code>가 공유용 텍스트를 만듭니다. 예: &quot;🙏 오늘의 감사 … Grato에서 감사한 순간을 함께 나눠요. {URL}&quot;. <code>{URL}</code>은 짧은 링크, 없으면 긴 링크입니다(<a href="#short-links">짧은 링크</a>). <code>navigator.share</code>가 있으면 공유 시트, 없으면 클립보드에 복사합니다.</p><h2 id="캘린더-png-내보내기" tabindex="-1">캘린더 PNG 내보내기 <a class="header-anchor" href="#캘린더-png-내보내기" aria-label="Permalink to &quot;캘린더 PNG 내보내기&quot;">​</a></h2><p>MyPage의 캘린더 카드(다른 카드와 같은 흰 카드, 제목 오른쪽에 월 이동, 아래에 그 달의 기록한 날 수와 연속일 — 지난달은 그 달의 최장 연속)는 PNG 이미지로 저장·공유할 수 있습니다. 이미지는 카드 화면을 그대로 찍지 않고 따뜻한 배경의 포스터 모양으로 따로 그리고, 맨 아래에 로고(새싹 마크 + Grato 글자, <code>brandArt.js</code>의 같은 도형)와 &quot;감사를 함께 나누는 공간&quot;을 넣습니다. 이미지는 <code>src/lib/calendarImage.js</code>가 카드와 같은 배치로 캔버스에 직접 그립니다(가로 1080px). 화면을 캡처하던 html2canvas는 날짜 숫자가 동그라미 아래로 쏠리고 이미지 크기가 화면 폭에 따라 달라져 2026-10에 바꿨습니다. 이미지는 기기에서 만들어지므로 공개 설정과 관계없습니다.</p><p>글자 색은 모두 바탕 위에서 AA(4.5:1) 이상입니다(2026-10, 옅은 회색·밝은 주황을 진하게).</p><p>저장 버튼은 미리보기 시트(<code>ImageShareSheet</code>)를 엽니다. 시즌 배지로 받은 이미지 테마(겨울·신년·가을)가 있으면 칩으로 골라 그 모습으로 저장합니다. 감사 글(작성자, 글 상세 › &quot;이미지&quot;)·배지(배지 상세)·Circle 초대장(Circle 설정 › 초대)도 같은 시트로 이미지를 만듭니다. → <a href="/grato-docs/features/stats-badges#themes">이미지 테마</a></p>`,57)])])}const g=e(d,[["render",r]]);export{p as __pageData,g as default};
